<?php require_once __DIR__.'/../config/db.php'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']??''); $password=$_POST['password']??''; $s=$pdo->prepare('SELECT * FROM users WHERE email=? AND active=1'); $s->execute([$email]); $u=$s->fetch(); if($u && password_verify($password,$u['password'])){session_regenerate_id(true); $_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']]; header('Location: '.($u['role']==='admin'?'../admin/dashboard.php':'../usuario/dashboard.php')); exit;} $error='Correo o contraseña incorrectos, o cuenta inactiva.'; }
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Iniciar sesión</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="../assets/css/estilos.css"></head><body class="auth-bg"><form class="form-card" method="post"><a href="../index.php" class="back">← Inicio</a><h1>Bienvenido</h1><p>Ingresa a tu espacio de aprendizaje.</p><?php if(isset($_GET['registered'])): ?><div class="success">Cuenta creada. Ya puedes iniciar sesión.</div><?php endif; ?><?php if($error): ?><div class="alert"><?=e($error)?></div><?php endif; ?><label>Correo electrónico</label><input name="email" type="email" required><label>Contraseña</label><input name="password" type="password" required><button class="btn full">Ingresar</button><p>¿No tienes cuenta? <a href="register.php">Regístrate</a></p></form></body></html>